pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        // We cannot actually call transferFrom on arbitrary address, so we wrap in try/catch
        // to catch reverts. The reference should succeed, the mutant should revert.
        try c.transfer(from, caddress, _tos, v) {
            // Reference returns true
            assertTrue(true);
        } catch {
            assertTrue(false);
        }
    }
}

